(7347211, 1148231, 115814, '<td valign="top">Didn''t know this existed. What a powerful statement. Modern and historical at the same time. Excellent entry.</td>', 'Didn''t know this existed. What a powerful statement. Modern and historical at the same time. Excellent entry.', '2015-05-03 13:32:01.000000', NULL, 1),
(7347213, 1148176, 115814, '<td valign="top">Normally, I''m not drawn to photos of statues, however, the careful composition and POV you''ve captured serves well to convey the spirit of joy you intended. Kudos.</td>', 'Normally, I''m not drawn to photos of statues, however, the careful composition and POV you''ve captured serves well to convey the spirit of joy you intended. Kudos.', '2015-05-03 13:33:35.000000', NULL, 1),
(7347215, 1148435, 115814, '<td valign="top">Simple elegance and lines and content.</td>', 'Simple elegance and lines and content.', '2015-05-03 13:34:24.000000', NULL, 1),
(7347216, 1148186, 115814, '<td valign="top">I was not familiar with this monument before seeing this. Your inclusion of children and father(?) surrounding the bronze statue of the young girl brings a poignancy to the image that increases it''s power. It''s relatively easy to photograph a monument. To do so with human context that amplifies the memorial intent, not so much. Terrific entry, among my top picks.</td>', 'I was not familiar with this monument before seeing this. Your inclusion of children and father(?) surrounding the bronze statue of the young girl brings a poignancy to the image that increases it''s power. It''s relatively easy to photograph a monument. To do so with human context that amplifies the memorial intent, not so much. Terrific entry, among my top picks.', '2015-05-03 13:38:27.000000', NULL, 1),
(7347217, 1148152, 115814, '<td valign="top">Didn''t know the name Vasily Zaytsev before seeing this. The composition alone captured my attention, becoming even stronger as I understood the context. Kudos.</td>', 'Didn''t know the name Vasily Zaytsev before seeing this. The composition alone captured my attention, becoming even stronger as I understood the context. Kudos.', '2015-05-03 13:41:16.000000', NULL, 1),
(7347218, 1148303, 115814, '<td valign="top">A simple, serene scene, made more poignant by excellent compositional and toning choices. Nicely done on all counts.</td>', 'A simple, serene scene, made more poignant by excellent compositional and toning choices. Nicely done on all counts.', '2015-05-03 13:43:19.000000', NULL, 1),
(7347219, 1148447, 115814, '<td valign="top">Simplicity with a bold minimal composition. Calming and intriguing.</td>', 'Simplicity with a bold minimal composition. Calming and intriguing.', '2015-05-03 13:44:07.000000', NULL, 1),
(7347220, 1147987, 115814, '<td valign="top">For me, it''s hard to capture and hold my attention with sculpture alone. Yet, here the quality of the work itself, the context provided by the background, and the choices in image toning make this work well. The main subject''s positioning against the simplest part of the background adds to the composition''s balance and focus. Nice work!</td>', 'For me, it''s hard to capture and hold my attention with sculpture alone. Yet, here the quality of the work itself, the context provided by the background, and the choices in image toning make this work well. The main subject''s positioning against the simplest part of the background adds to the composition''s balance and focus. Nice work!', '2015-05-03 13:47:30.000000', NULL, 1),
(7347222, 1148122, 115814, '<td valign="top">Excellent low key work. Subtle shadow detail fading to black, well-balance composition.</td>', 'Excellent low key work. Subtle shadow detail fading to black, well-balance composition.', '2015-05-03 13:48:58.000000', NULL, 1),
