(7347695, 1148458, 179608, '<td valign="top">The process used for this image is the HDR tecnique; in this photo I think that it doesn''t give the right result due to the fact that the background is too much important and the colours are similar to the monument''s ones.<br/>It''s a pity cause the monument has the perfect parameters for the contest and i think you''d have to isolate it from the rest to have the perfect result</td>', 'The process used for this image is the HDR tecnique; in this photo I think that it doesn''t give the right result due to the fact that the background is too much important and the colours are similar to the monument''s ones.It''s a pity cause the monument has the perfect parameters for the contest and i think you''d have to isolate it from the rest to have the perfect result', '2015-05-04 15:46:55.000000', NULL, 0),
(7347699, 1148186, 50695, '<td valign="top">it''s all in the way he is unconsciously leaning on the statue, and the way the statue is unconsciously holding him up.</td>', 'it''s all in the way he is unconsciously leaning on the statue, and the way the statue is unconsciously holding him up.', '2015-05-04 16:02:29.000000', NULL, 0),
